arguments.content:
@import url('https://fonts.googleapis.com/css2?family=Oswald:wght@400;500;600;700&family=Inter:wght@300;400;500;600;700&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --bg-primary: #111111;
  --bg-secondary: #1A1A1A;
  --bg-tertiary: #222222;
  --red: #E63946;
  --red-dark: #C5303C;
  --red-glow: rgba(230, 57, 70, 0.3);
  --white: #FFFFFF;
  --gray-100: #F5F5F5;
  --gray-300: #CCCCCC;
  --gray-400: #999999;
  --gray-500: #777777;
  --gray-700: #444444;
  --gray-800: #2A2A2A;
  --font-display: 'Oswald', 'Arial Narrow', sans-serif;
  --font-body: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --transition: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  --max-width: 1280px;
}

html { scroll-behavior: smooth; }

body {
  font-family: var(--font-body);
  background: var(--bg-primary);
  color: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

a { color: inherit; text-decoration: none; }
img { max-width: 100%; display: block; }
button { cursor: pointer; font-family: inherit; }
ul { list-style: none; }

.container { max-width: var(--max-width); margin: 0 auto; padding: 0 24px; }

/* ── Top Promo Bar ── */
.promo-bar {
  background: var(--red);
  text-align: center;
  padding: 10px 24px;
  font-family: var(--font-body);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.5px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
}
.promo-bar a {
  font-weight: 700;
  text-decoration: underline;
  text-underline-offset: 2px;
}
.promo-bar a:hover { opacity: 0.85; }

/* ── Navigation ── */
.nav-wrapper {
  position: sticky;
  top: 0;
  z-index: 1000;
  background: rgba(17, 17, 17, 0.95);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid rgba(255,255,255,0.06);
}
.nav {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 24px;
  height: 72px;
  max-width: var(--max-width);
  margin: 0 auto;
}
.nav-logo {
  font-family: var(--font-display);
  font-size: 22px;
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  white-space: nowrap;
}
.nav-logo span { color: var(--red); }
.nav-links {
  display: flex;
  align-items: center;
  gap: 32px;
}
.nav-links a {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--gray-300);
  transition: color var(--transition);
  white-space: nowrap;
}
.nav-links a:hover, .nav-links a.active { color: var(--white); }
.nav-cta {
  display: flex;
  align-items: center;
  gap: 12px;
}
.nav-cta .btn-sm {
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  padding: 10px 20px;
  border: none;
  transition: all var(--transition);
}
.btn-red {
  background: var(--red);
  color: var(--white);
}
.btn-red:hover { background: var(--red-dark); }
.btn-outline {
  background: transparent;
  color: var(--white);
  border: 1px solid rgba(255,255,255,0.25) !important;
}
.btn-outline:hover { border-color: var(--white) !important; }

/* Mobile Nav */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  padding: 4px;
}
.nav-toggle span {
  width: 24px;
  height: 2px;
  background: var(--white);
  transition: all var(--transition);
}
.nav-toggle.open span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
.nav-toggle.open span:nth-child(2) { opacity: 0; }
.nav-toggle.open span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

@media (max-width: 1024px) {
  .nav-links, .nav-cta { display: none; }
  .nav-toggle { display: flex; }
  .mobile-menu {
    display: none;
    position: fixed;
    top: 72px;
    left: 0; right: 0; bottom: 0;
    background: var(--bg-primary);
    padding: 40px 24px;
    z-index: 999;
    flex-direction: column;
    gap: 0;
    overflow-y: auto;
  }
  .mobile-menu.open { display: flex; }
  .mobile-menu a {
    font-family: var(--font-display);
    font-size: 20px;
    font-weight: 500;
    letter-spacing: 2px;
    text-transform: uppercase;
    color: var(--gray-300);
    padding: 16px 0;
    border-bottom: 1px solid rgba(255,255,255,0.06);
    transition: color var(--transition);
  }
  .mobile-menu a:hover { color: var(--white); }
  .mobile-menu .mobile-cta {
    margin-top: 32px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .mobile-menu .mobile-cta a {
    text-align: center;
    padding: 14px 24px;
    border-bottom: none;
    font-size: 14px;
  }
}

/* ── Buttons ── */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  border: none;
  transition: all var(--transition);
  cursor: pointer;
}
.btn-lg {
  font-size: 16px;
  padding: 18px 48px;
}
.btn-md {
  font-size: 14px;
  padding: 14px 36px;
}
.btn-primary {
  background: var(--red);
  color: var(--white);
}
.btn-primary:hover {
  background: var(--red-dark);
  box-shadow: 0 0 30px var(--red-glow);
}
.btn-ghost {
  background: transparent;
  color: var(--white);
  border: 2px solid var(--white);
}
.btn-ghost:hover { background: rgba(255,255,255,0.1); }

/* ── Hero Section ── */
.hero {
  position: relative;
  min-height: 85vh;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  padding: 120px 24px 80px;
  overflow: hidden;
}
.hero::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center bottom, rgba(230,57,70,0.15) 0%, transparent 70%);
  pointer-events: none;
}
.hero-content { position: relative; z-index: 2; max-width: 800px; }
.hero-tag {
  display: inline-block;
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 3px;
  text-transform: uppercase;
  color: var(--red);
  margin-bottom: 24px;
}
.hero h1 {
  font-family: var(--font-display);
  font-size: clamp(40px, 7vw, 80px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  line-height: 1.05;
  margin-bottom: 24px;
}
.hero h1 .accent { color: var(--red); }
.hero p {
  font-size: 18px;
  color: var(--gray-300);
  max-width: 580px;
  margin: 0 auto 40px;
  line-height: 1.7;
}
.hero-btns {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

.hero-sm {
  min-height: 50vh;
  padding: 100px 24px 60px;
}
.hero-sm h1 { font-size: clamp(36px, 5vw, 64px); }

/* ── Section Defaults ── */
.section {
  padding: 100px 0;
}
.section-dark { background: var(--bg-secondary); }
.section-header {
  text-align: center;
  margin-bottom: 64px;
}
.section-header h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.section-header p {
  font-size: 16px;
  color: var(--gray-400);
  max-width: 600px;
  margin: 0 auto;
  line-height: 1.7;
}
.section-header .divider {
  width: 60px;
  height: 3px;
  background: var(--red);
  margin: 20px auto 0;
}

/* ── Community Promo ── */
.community {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.community-img {
  aspect-ratio: 4/3;
  background: var(--bg-tertiary);
  border-radius: 4px;
  overflow: hidden;
  position: relative;
}
.community-img::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(230,57,70,0.2), transparent);
}
.community-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-display);
  font-size: 48px;
  color: rgba(255,255,255,0.08);
  letter-spacing: 4px;
}
.community-text h2 {
  font-family: var(--font-display);
  font-size: clamp(32px, 4vw, 52px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 20px;
}
.community-text p {
  font-size: 16px;
  color: var(--gray-400);
  line-height: 1.8;
  margin-bottom: 32px;
}
@media (max-width: 768px) {
  .community { grid-template-columns: 1fr; gap: 40px; }
}

/* ── Two Ways ── */
.two-ways-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 32px;
}
.two-ways-card {
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 48px;
  text-align: center;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.two-ways-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0; right: 0;
  height: 3px;
  background: var(--red);
  transform: scaleX(0);
  transition: transform var(--transition);
}
.two-ways-card:hover::before { transform: scaleX(1); }
.two-ways-card:hover {
  border-color: rgba(230,57,70,0.3);
  transform: translateY(-4px);
}
.two-ways-card .card-icon {
  width: 64px;
  height: 64px;
  margin: 0 auto 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(230,57,70,0.1);
}
.two-ways-card .card-icon svg {
  width: 28px;
  height: 28px;
  stroke: var(--red);
  fill: none;
  stroke-width: 2;
}
.two-ways-card h3 {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.two-ways-card p {
  font-size: 15px;
  color: var(--gray-400);
  line-height: 1.7;
}
@media (max-width: 768px) {
  .two-ways-grid { grid-template-columns: 1fr; }
  .two-ways-card { padding: 36px 24px; }
}

/* ── Studio Experience ── */
.studio-exp {
  position: relative;
  padding: 120px 0;
  text-align: center;
  overflow: hidden;
}
.studio-exp::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(230,57,70,0.08), transparent 50%, rgba(230,57,70,0.05));
  pointer-events: none;
}
.studio-exp h2 {
  font-family: var(--font-display);
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 20px;
  position: relative;
}
.studio-exp p {
  font-size: 16px;
  color: var(--gray-400);
  max-width: 640px;
  margin: 0 auto 40px;
  line-height: 1.8;
  position: relative;
}

/* ── Free Trial CTA ── */
.free-trial {
  background: var(--red);
  text-align: center;
  padding: 80px 24px;
  position: relative;
  overflow: hidden;
}
.free-trial::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(0,0,0,0.2), transparent);
  pointer-events: none;
}
.free-trial h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 28px;
  position: relative;
}
.free-trial .btn {
  position: relative;
  background: var(--white);
  color: var(--bg-primary);
}
.free-trial .btn:hover {
  background: var(--gray-100);
  box-shadow: 0 0 30px rgba(255,255,255,0.3);
}

/* ── Carousel ── */
.carousel-section { overflow: hidden; }
.carousel-wrapper { position: relative; }
.carousel-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.carousel-slide {
  min-width: 100%;
  aspect-ratio: 21/9;
  background: var(--bg-tertiary);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.carousel-slide::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(17,17,17,0.6), transparent 40%);
}
.carousel-slide-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  position: relative;
  z-index: 1;
}
.carousel-slide-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-slide-bg svg { opacity: 0.06; }
.carousel-label {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.12);
  position: relative;
  z-index: 2;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.7);
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn svg { width: 20px; height: 20px; }
.carousel-prev { left: 16px; }
.carousel-next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 24px 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-700);
  border: none;
  transition: all var(--transition);
}
.carousel-dot.active {
  background: var(--red);
  box-shadow: 0 0 8px var(--red-glow);
}

/* ── Newsletter ── */
.newsletter {
  background: var(--bg-secondary);
  padding: 80px 0;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3vw, 36px);
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--gray-400);
  font-size: 15px;
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
  gap: 0;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.1);
  border-right: none;
  color: var(--white);
  font-family: var(--font-body);
  font-size: 14px;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: var(--gray-500); }
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: #FF6B6B; }
.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  color: var(--white);
  border: none;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-feedback {
  font-size: 13px;
  margin-top: 12px;
  min-height: 20px;
}
.newsletter-feedback.success { color: #4CAF50; }
.newsletter-feedback.error { color: #FF6B6B; }
@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
  .newsletter-form input { border-right: 1px solid rgba(255,255,255,0.1); border-bottom: none; }
}

/* ── Footer ── */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 60px;
}
.footer-brand .nav-logo { margin-bottom: 16px; display: inline-block; }
.footer-brand p {
  color: var(--gray-500);
  font-size: 14px;
  line-height: 1.7;
  max-width: 280px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col a {
  display: block;
  color: var(--gray-500);
  font-size: 14px;
  padding: 6px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p {
  color: var(--gray-500);
  font-size: 13px;
}
.country-select {
  position: relative;
}
.country-select select {
  appearance: none;
  background: var(--bg-tertiary);
  color: var(--gray-300);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 8px 36px 8px 14px;
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition);
}
.country-select select:focus { border-color: var(--red); }
.country-select::after {
  content: '▾';
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-500);
  font-size: 12px;
  pointer-events: none;
}
@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ── The Workout Page ── */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.method-text h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.method-text p {
  font-size: 16px;
  color: var(--gray-400);
  line-height: 1.8;
}
.method-visual {
  aspect-ratio: 1;
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.method-visual::before {
  content: '';
  position: absolute;
  width: 200%;
  height: 200%;
  background: conic-gradient(from 0deg, transparent, rgba(230,57,70,0.05), transparent, rgba(230,57,70,0.05));
  animation: rotate 20s linear infinite;
}
@keyframes rotate { to { transform: rotate(360deg); } }
.method-visual-label {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.06);
  position: relative;
}
@media (max-width: 768px) {
  .method-grid { grid-template-columns: 1fr; gap: 40px; }
}

/* ── Schedule Table ── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}
.schedule-table thead th {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--red);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--red);
}
.schedule-table tbody tr {
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background var(--transition);
}
.schedule-table tbody tr:hover { background: rgba(230,57,70,0.05); }
.schedule-table td {
  padding: 20px 24px;
  font-size: 15px;
}
.schedule-table td:first-child {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.schedule-table td:last-child { color: var(--gray-300); }

