  position: absolute;
  inset: 0;
  background: linear-gradient(to top, rgba(17,17,17,0.6), transparent 40%);
}
.carousel-slide-inner {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  position: relative;
  z-index: 1;
}
.carousel-slide-bg {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
}
.carousel-slide-bg svg { opacity: 0.06; }
.carousel-label {
  font-family: var(--font-display);
  font-size: 24px;
  font-weight: 600;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.12);
  position: relative;
  z-index: 2;
}
.carousel-btn {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 52px;
  height: 52px;
  background: rgba(17,17,17,0.7);
  backdrop-filter: blur(4px);
  border: 1px solid rgba(255,255,255,0.1);
  color: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: all var(--transition);
}
.carousel-btn:hover {
  background: var(--red);
  border-color: var(--red);
}
.carousel-btn svg { width: 20px; height: 20px; }
.carousel-prev { left: 16px; }
.carousel-next { right: 16px; }
.carousel-dots {
  display: flex;
  justify-content: center;
  gap: 10px;
  padding: 24px 0;
}
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: var(--gray-700);
  border: none;
  transition: all var(--transition);
}
.carousel-dot.active {
  background: var(--red);
  box-shadow: 0 0 8px var(--red-glow);
}

/* ── Newsletter ── */
.newsletter {
  background: var(--bg-secondary);
  padding: 80px 0;
  text-align: center;
}
.newsletter h3 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3vw, 36px);
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.newsletter p {
  color: var(--gray-400);
  font-size: 15px;
  margin-bottom: 32px;
  max-width: 500px;
  margin-left: auto;
  margin-right: auto;
}
.newsletter-form {
  display: flex;
  max-width: 480px;
  margin: 0 auto;
  gap: 0;
}
.newsletter-form input {
  flex: 1;
  padding: 14px 20px;
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.1);
  border-right: none;
  color: var(--white);
  font-family: var(--font-body);
  font-size: 14px;
  outline: none;
  transition: border-color var(--transition);
}
.newsletter-form input::placeholder { color: var(--gray-500); }
.newsletter-form input:focus { border-color: var(--red); }
.newsletter-form input.error { border-color: #FF6B6B; }
.newsletter-form button {
  padding: 14px 28px;
  background: var(--red);
  color: var(--white);
  border: none;
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  white-space: nowrap;
  transition: background var(--transition);
}
.newsletter-form button:hover { background: var(--red-dark); }
.newsletter-feedback {
  font-size: 13px;
  margin-top: 12px;
  min-height: 20px;
}
.newsletter-feedback.success { color: #4CAF50; }
.newsletter-feedback.error { color: #FF6B6B; }
@media (max-width: 480px) {
  .newsletter-form { flex-direction: column; }
  .newsletter-form input { border-right: 1px solid rgba(255,255,255,0.1); border-bottom: none; }
}

/* ── Footer ── */
.footer {
  background: var(--bg-primary);
  border-top: 1px solid rgba(255,255,255,0.06);
  padding: 80px 0 40px;
}
.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 60px;
}
.footer-brand .nav-logo { margin-bottom: 16px; display: inline-block; }
.footer-brand p {
  color: var(--gray-500);
  font-size: 14px;
  line-height: 1.7;
  max-width: 280px;
}
.footer-col h4 {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--white);
  margin-bottom: 20px;
}
.footer-col a {
  display: block;
  color: var(--gray-500);
  font-size: 14px;
  padding: 6px 0;
  transition: color var(--transition);
}
.footer-col a:hover { color: var(--red); }
.footer-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 32px;
  border-top: 1px solid rgba(255,255,255,0.06);
  flex-wrap: wrap;
  gap: 16px;
}
.footer-bottom p {
  color: var(--gray-500);
  font-size: 13px;
}
.country-select {
  position: relative;
}
.country-select select {
  appearance: none;
  background: var(--bg-tertiary);
  color: var(--gray-300);
  border: 1px solid rgba(255,255,255,0.1);
  padding: 8px 36px 8px 14px;
  font-family: var(--font-body);
  font-size: 13px;
  cursor: pointer;
  outline: none;
  transition: border-color var(--transition);
}
.country-select select:focus { border-color: var(--red); }
.country-select::after {
  content: '▾';
  position: absolute;
  right: 12px;
  top: 50%;
  transform: translateY(-50%);
  color: var(--gray-500);
  font-size: 12px;
  pointer-events: none;
}
@media (max-width: 768px) {
  .footer-grid { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 480px) {
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; align-items: flex-start; }
}

/* ── The Workout Page ── */
.method-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 64px;
  align-items: center;
}
.method-text h2 {
  font-family: var(--font-display);
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 24px;
}
.method-text p {
  font-size: 16px;
  color: var(--gray-400);
  line-height: 1.8;
}
.method-visual {
  aspect-ratio: 1;
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.06);
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  overflow: hidden;
}
.method-visual::before {
  content: '';
  position: absolute;
  width: 200%;
  height: 200%;
  background: conic-gradient(from 0deg, transparent, rgba(230,57,70,0.05), transparent, rgba(230,57,70,0.05));
  animation: rotate 20s linear infinite;
}
@keyframes rotate { to { transform: rotate(360deg); } }
.method-visual-label {
  font-family: var(--font-display);
  font-size: 32px;
  font-weight: 700;
  letter-spacing: 4px;
  text-transform: uppercase;
  color: rgba(255,255,255,0.06);
  position: relative;
}
@media (max-width: 768px) {
  .method-grid { grid-template-columns: 1fr; gap: 40px; }
}

/* ── Schedule Table ── */
.schedule-table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 8px;
}
.schedule-table thead th {
  font-family: var(--font-display);
  font-size: 13px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  color: var(--red);
  text-align: left;
  padding: 16px 24px;
  border-bottom: 2px solid var(--red);
}
.schedule-table tbody tr {
  border-bottom: 1px solid rgba(255,255,255,0.06);
  transition: background var(--transition);
}
.schedule-table tbody tr:hover { background: rgba(230,57,70,0.05); }
.schedule-table td {
  padding: 20px 24px;
  font-size: 15px;
}
.schedule-table td:first-child {
  font-family: var(--font-display);
  font-weight: 600;
  font-size: 16px;
  letter-spacing: 1px;
  text-transform: uppercase;
}
.schedule-table td:last-child { color: var(--gray-300); }

/* ── Floor / Treadmill Toggle ── */
.toggle-section { text-align: center; }
.toggle-switch {
  display: inline-flex;
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.08);
  padding: 4px;
  gap: 4px;
  margin-bottom: 48px;
}
.toggle-btn {
  font-family: var(--font-display);
  font-size: 14px;
  font-weight: 600;
  letter-spacing: 2px;
  text-transform: uppercase;
  padding: 12px 32px;
  background: transparent;
  color: var(--gray-500);
  border: none;
  transition: all var(--transition);
}
.toggle-btn.active {
  background: var(--red);
  color: var(--white);
}
.toggle-btn:hover:not(.active) { color: var(--white); }
.toggle-content {
  max-width: 700px;
  margin: 0 auto;
  text-align: center;
}
.toggle-panel { display: none; }
.toggle-panel.active { display: block; animation: fadeUp 0.4s ease; }
@keyframes fadeUp {
  from { opacity: 0; transform: translateY(12px); }
  to { opacity: 1; transform: translateY(0); }
}
.toggle-panel h3 {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  letter-spacing: 2px;
  text-transform: uppercase;
  margin-bottom: 16px;
}
.toggle-panel p {
  font-size: 16px;
  color: var(--gray-400);
  line-height: 1.8;
}
.toggle-icon {
  width: 80px;
  height: 80px;
  margin: 0 auto 24px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 50%;
  background: rgba(230,57,70,0.1);
  border: 2px solid rgba(230,57,70,0.2);
}
.toggle-icon svg {
  width: 36px;
  height: 36px;
  stroke: var(--red);
  fill: none;
  stroke-width: 1.5;
}

/* ── Instructors ── */
.filter-bar {
  display: flex;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-bottom: 48px;
}
.filter-btn {
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  padding: 10px 24px;
  background: transparent;
  color: var(--gray-500);
  border: 1px solid rgba(255,255,255,0.1);
  transition: all var(--transition);
}
.filter-btn.active, .filter-btn:hover {
  background: var(--red);
  color: var(--white);
  border-color: var(--red);
}
.instructor-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: 24px;
}
.instructor-card {
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.06);
  overflow: hidden;
  transition: all var(--transition);
}
.instructor-card:hover {
  border-color: rgba(230,57,70,0.3);
  transform: translateY(-4px);
}
.instructor-card.hidden {
  display: none;
}
.instructor-img {
  aspect-ratio: 3/4;
  background: var(--bg-secondary);
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
}
.instructor-img::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0; right: 0;
  height: 50%;
  background: linear-gradient(to top, var(--bg-tertiary), transparent);
}
.instructor-initials {
  font-family: var(--font-display);
  font-size: 48px;
  font-weight: 700;
  color: rgba(255,255,255,0.06);
  letter-spacing: 4px;
}
.instructor-info {
  padding: 20px 24px;
}
.instructor-info h3 {
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 4px;
}
.instructor-info .location {
  font-size: 13px;
  color: var(--gray-500);
  margin-bottom: 16px;
}
.instructor-info .book-link {
  font-family: var(--font-display);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 1.5px;
  text-transform: uppercase;
  color: var(--red);
  transition: color var(--transition);
}
.instructor-info .book-link:hover { color: var(--white); }
.instructor-info .book-link::after { content: ' →'; }

/* ── FAQ Accordion ── */
.faq-list { max-width: 800px; margin: 0 auto; }
.faq-item {
  border-bottom: 1px solid rgba(255,255,255,0.08);
}
.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 24px 0;
  background: none;
  border: none;
  color: var(--white);
  font-family: var(--font-display);
  font-size: 18px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  text-align: left;
  cursor: pointer;
  transition: color var(--transition);
}
.faq-question:hover { color: var(--red); }
.faq-question .icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  margin-left: 16px;
  transition: transform var(--transition);
  stroke: var(--gray-500);
  fill: none;
  stroke-width: 2;
}
.faq-item.open .faq-question .icon { transform: rotate(45deg); stroke: var(--red); }
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.4s cubic-bezier(0.4, 0, 0.2, 1), padding 0.4s;
}
.faq-item.open .faq-answer { max-height: 300px; }
.faq-answer-inner {
  padding: 0 0 24px;
  font-size: 15px;
  color: var(--gray-400);
  line-height: 1.8;
}

/* ── Digital Platform ── */
.features-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 32px;
}
.feature-card {
  background: var(--bg-tertiary);
  border: 1px solid rgba(255,255,255,0.06);
  padding: 40px 32px;
  transition: all var(--transition);
  position: relative;
  overflow: hidden;
}
.feature-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 3px;
  height: 100%;
  background: var(--red);
  transform: scaleY(0);
  transform-origin: bottom;
  transition: transform var(--transition);
}
.feature-card:hover::before { transform: scaleY(1); }
.feature-card:hover {
  border-color: rgba(230,57,70,0.2);
  transform: translateY(-4px);
}
.feature-icon {
  width: 52px;
  height: 52px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 12px;
  background: rgba(230,57,70,0.1);
  margin-bottom: 20px;
}
.feature-icon svg {
  width: 24px;
  height: 24px;
  stroke: var(--red);
  fill: none;
  stroke-width: 2;
}
.feature-card h3 {
  font-family: var(--font-display);
  font-size: 20px;
  font-weight: 600;
  letter-spacing: 1px;
  text-transform: uppercase;
  margin-bottom: 12px;
}
.feature-card p {
  font-size: 14px;
  color: var(--gray-400);
  line-height: 1.7;
}

/* ── CTA Banner ── */
.cta-banner {
  text-align: center;
  padding: 80px 24px;
  background: var(--bg-secondary);
  position: relative;
}
.cta-banner::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse at center, rgba(230,57,70,0.08), transparent 70%);
}
.cta-banner h2 {
  font-family: var(--font-display);
  font-size: clamp(24px, 3vw, 40px);
  font-weight: 700;
  letter-spacing: 3px;
  text-transform: uppercase;
  margin-bottom: 12px;
  position: relative;
}
.cta-banner p {
  color: var(--gray-400);
  font-size: 16px;
  margin-bottom: 32px;
  position: relative;
}
.cta-banner .btn { position: relative; }

/* ── Utilities ── */
.text-red { color: var(--red); }
.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden;
  clip: rect(0,0,0,0);
  border: 0;
